argv:
$ErrorActionPreference='Stop'
$sw=[Diagnostics.Stopwatch]::StartNew()
$marks=[ordered]@{}
function Mark([string]$n){$marks[$n]=[math]::Round($sw.Elapsed.TotalSeconds,2)}
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32Fast {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
[W32Fast]::ShowWindow($edge.MainWindowHandle,9)|Out-Null
[W32Fast]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
Mark 'edge_ready'

# Gemini
[System.Windows.Forms.SendKeys]::SendWait('^l')
[System.Windows.Forms.SendKeys]::SendWait('https://gemini.google.com/app')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 5
Mark 'gemini_open'

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$edit=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit){
   $r=$e.Current.BoundingRectangle
   if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 450 -and $r.Width -gt 300){$edit=$e;break}
 }
}
if($null -eq $edit){throw 'Gemini prompt edit not found'}
$edit.SetFocus()
$prompt=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Set-Clipboard -Value $prompt
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^v')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Mark 'gemini_prompt_sent'
Start-Sleep -Seconds 28

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$downloadText=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5LiL6LyJ5Y6f5bC65a+45ZyW54mH'))
$btn=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $downloadText){$btn=$e;break}
}
if($null -eq $btn){throw 'Gemini download button not found after wait'}
$inv=$btn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern);$inv.Invoke()
Start-Sleep -Seconds 7
$downloads=Join-Path $env:USERPROFILE 'Downloads'
$img=Get-ChildItem -LiteralPath $downloads -File | Where-Object {$_.Extension -match '(?i)^\.(png|jpg|jpeg|webp)$'} | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if($null -eq $img){throw 'No downloaded image found'}
Mark 'gemini_image_downloaded'

# Threads
[W32Fast]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
[System.Windows.Forms.SendKeys]::SendWait('^l')
[System.Windows.Forms.SendKeys]::SendWait('https://www.threads.com/')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 6
Mark 'threads_open'

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$entryName=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5paH5a2X5qyE5L2N56m655m944CC6KuL6Ly45YWl5YWn5a655Lul5pSw5a+r5paw6LK85paH44CC'))
$entry=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $entryName){$entry=$e;break}
}
if($null -eq $entry){throw 'Threads composer entry not found'}
$entry.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()
Start-Sleep -Seconds 2
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$editName=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5paH5a2X5qyE5L2N56m655m944CC6KuL6Ly45YWl5YWn5a655Lul5pSw5a+r5paw6LK85paH44CC'))
$attachName=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('6ZmE5Yqg5b2x6Z+z5YWn5a65'))
$postEdit=$null;$attach=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.Name -eq $editName){$postEdit=$e}
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $attachName){$attach=$e}
}
if($null -eq $postEdit -or $null -eq $attach){throw 'Threads composer controls missing'}
$postEdit.SetFocus()
$post=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Set-Clipboard -Value $post
[System.Windows.Forms.SendKeys]::SendWait('^a');[System.Windows.Forms.SendKeys]::SendWait('^v')
$attach.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()
Start-Sleep -Seconds 2

$desk=[System.Windows.Automation.AutomationElement]::RootElement
$all2=$desk.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$fileEdit=$null
for($i=0;$i -lt $all2.Count;$i++){
 $e=$all2.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.AutomationId -eq '1148'){$fileEdit=$e;break}
}
if($null -eq $fileEdit){throw 'File picker filename field not found'}
$vp=$fileEdit.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
$vp.SetValue($img.FullName)
$fileEdit.SetFocus();[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 6
Mark 'threads_draft_ready'

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$publish=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq '發佈' -and $e.Current.IsEnabled){
   $r=$e.Current.BoundingRectangle
   if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 450){$publish=$e;break}
 }
}
if($null -eq $publish){throw 'Threads publish button not found'}
$publish.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()
Mark 'publish_invoked'
Start-Sleep -Seconds 10

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$needle=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('56ys5LqM6LyqIEFnZW50T1MgR1VJIERlbW8='))
$found=$false
for($i=0;$i -lt $all.Count;$i++){
 $name=[string]$all.Item($i).Current.Name
 if($name -like ('*'+$needle+'*')){$found=$true;break}
}
Mark 'verification_done'
[pscustomobject]@{ok=$found;image=$img.FullName;image_bytes=$img.Length;marks=$marks;elapsed_seconds=[math]::Round($sw.Elapsed.TotalSeconds,2)}|ConvertTo-Json -Depth 6 -Compress
